export function FontSize({
  size = {{size}},
  text = "{{text}}",
  weight = "{{weight}}",
  color = "{{color}}",
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <p style={{ margin: 0, fontSize: size, fontWeight: Number(weight), color }}>{text}</p>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>font-size: {size}px</p>
    </div>
  );
}
